// Dataflow: minimal SOP expressions (F' has its own minimal SOP)
module demo_dc_df (input A, input B, input C, input D, output F, output F_n);
    assign F  = (~A & ~B) | (C & D);
    assign F_n = (~D) | (A & ~C);
endmodule

// AND-OR-INV (SOP): F' = INV(SOP of F), F = INV(SOP of F'); 2-input AND/OR + NOT
module demo_dc_aoi (
    input A, input B, input C, input D,
    output F,
    output F_n
);
    wire n1, n2, n3, n4, n5, n7, n8, n9, n10;
    not g1 (n1, A);
    not g2 (n2, B);
    and g3 (n3, n1, n2);
    and g4 (n4, C, D);
    or g5 (n5, n3, n4);
    not g6 (F_n, n5);
    not g7 (n7, D);
    not g8 (n8, C);
    and g9 (n9, A, n8);
    or g10 (n10, n7, n9);
    not g11 (F, n10);
endmodule

// OR-AND-INV (POS): F' = INV(POS of F), F = INV(POS of F'); 2-input OR/AND + NOT
